CREATE OR REPLACE FUNCTION public.admin_link_lobby_match(p_lobby_id bigint,p_match_code text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_lobby active_async_matches%ROWTYPE; v_game uuid; BEGIN IF auth.uid() IS NULL OR NOT (has_role(auth.uid(),'admin') OR has_role(auth.uid(),'lfg_admin')) THEN RAISE EXCEPTION 'LFG admins only'; END IF; PERFORM pg_advisory_xact_lock(hashtext('admin-lobby-revert')); SELECT * INTO v_lobby FROM active_async_matches WHERE id=p_lobby_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Lobby not found'; END IF; IF nullif(btrim(p_match_code),'') IS NULL THEN UPDATE active_async_matches SET linked_game_id=NULL,league_status=CASE WHEN is_league THEN NULL ELSE league_status END WHERE id=p_lobby_id; RETURN jsonb_build_object('ok',true); END IF; SELECT id INTO v_game FROM games WHERE upper(public_match_id)=upper(regexp_replace(btrim(p_match_code),'^#+','')) OR id::text=btrim(p_match_code) LIMIT 1 FOR UPDATE; IF v_game IS NULL THEN RAISE EXCEPTION 'Match not found'; END IF; IF EXISTS(SELECT 1 FROM active_async_matches WHERE linked_game_id=v_game AND id<>p_lobby_id) THEN RAISE EXCEPTION 'This match is already linked to another lobby'; END IF; UPDATE active_async_matches SET linked_game_id=v_game,status='started',league_status=CASE WHEN is_league THEN 'reported' ELSE league_status END WHERE id=p_lobby_id; IF v_lobby.is_league THEN UPDATE games SET is_league=true WHERE id=v_game; END IF; INSERT INTO lfg_lobby_events(lobby_id,actor_name,kind,detail) VALUES(p_lobby_id,auth.uid()::text,'admin_link','Linked match '||p_match_code); RETURN jsonb_build_object('ok',true,'game_id',v_game); END; $$; REVOKE ALL ON FUNCTION public.admin_link_lobby_match(bigint,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_link_lobby_match(bigint,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_revert_match_and_sp(p_lobby_id bigint DEFAULT NULL,p_game_id uuid DEFAULT NULL,p_delete_result boolean DEFAULT false,p_confirmed boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_lobby active_async_matches%ROWTYPE; v_game uuid:=p_game_id; v_sp record; v_total bigint:=0; v_result jsonb; BEGIN IF auth.uid() IS NULL OR NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Main admins only'; END IF; IF NOT p_confirmed OR (p_lobby_id IS NULL AND p_game_id IS NULL) THEN RAISE EXCEPTION 'Explicit confirmation and a match or lobby are required'; END IF; PERFORM pg_advisory_xact_lock(hashtext('admin-lobby-revert')); IF p_lobby_id IS NOT NULL THEN SELECT * INTO v_lobby FROM active_async_matches WHERE id=p_lobby_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Lobby not found'; END IF; IF p_game_id IS NOT NULL AND v_lobby.linked_game_id IS DISTINCT FROM p_game_id THEN RAISE EXCEPTION 'Lobby result changed; refresh before reverting'; END IF; v_game:=v_lobby.linked_game_id; ELSE SELECT * INTO v_lobby FROM active_async_matches WHERE linked_game_id=p_game_id ORDER BY id LIMIT 1 FOR UPDATE; END IF; IF v_game IS NOT NULL AND NOT p_delete_result THEN RAISE EXCEPTION 'A result exists: use Delete result and revert SP/Elo'; END IF; IF v_game IS NOT NULL THEN PERFORM 1 FROM games WHERE id=v_game FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Result no longer exists'; END IF; IF EXISTS(SELECT 1 FROM active_async_matches l JOIN player_league_ratings r ON r.season=coalesce(l.season_num,l.season_id) JOIN game_results gr ON gr.game_id=v_game AND r.player_key=lower(btrim(gr.player_name)) WHERE l.linked_game_id=v_game AND l.is_league AND r.games_played>0) THEN RAISE EXCEPTION 'League Elo has been applied, but the bot has not stored per-match League deltas. No changes were made; reversible League deltas are required first'; END IF; v_result:=delete_game_with_rating_revert(v_game); END IF; FOR v_sp IN WITH removed AS (DELETE FROM sp_events WHERE metadata->>'match_id'=v_lobby.id::text AND action_type IN ('match_start_base','first_live_game','first_weekly_async') RETURNING player_key,season_id,amount,is_legacy) SELECT player_key,season_id,sum(amount)::integer total,sum(CASE WHEN is_legacy THEN 0 ELSE amount END)::integer seasonal FROM removed GROUP BY player_key,season_id LOOP UPDATE player_sp SET lifetime_sp=greatest(0,lifetime_sp-v_sp.total),seasonal_sp=CASE WHEN season_id=v_sp.season_id THEN greatest(0,seasonal_sp-v_sp.seasonal) ELSE seasonal_sp END,updated_at=now() WHERE player_key=v_sp.player_key; UPDATE player_season_sp SET seasonal_sp=greatest(0,seasonal_sp-v_sp.seasonal),updated_at=now() WHERE player_key=v_sp.player_key AND season_id=v_sp.season_id; v_total:=v_total+v_sp.total; END LOOP; IF v_lobby.id IS NOT NULL THEN UPDATE active_async_matches SET status='cancelled',linked_game_id=NULL,league_status=CASE WHEN is_league THEN 'cancelled' ELSE league_status END,auto_start_at=NULL WHERE id=v_lobby.id; INSERT INTO lfg_lobby_events(lobby_id,actor_name,kind,detail) VALUES(v_lobby.id,auth.uid()::text,'admin_revert','Reverted start SP: '||v_total||CASE WHEN v_game IS NOT NULL THEN '; deleted result '||v_game::text||' with result SP and Elo reversal' ELSE '' END); END IF; RETURN jsonb_build_object('ok',true,'start_sp_reverted',v_total,'game_deleted',v_game); END; $$; REVOKE ALL ON FUNCTION public.admin_revert_match_and_sp(bigint,uuid,boolean,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_revert_match_and_sp(bigint,uuid,boolean,boolean) TO authenticated;